import json
import math
from pyscipopt import Model, quicksum

data = json.load(open('/root/data.json'))
depot = data['depot']
stations_data = data['stations']
n = len(stations_data)
K = data['vehicle_count']
CAP = data['vehicle_capacity']
PEN = data['penalty_weight']
R = 3960.0

station_ids = [int(s['id']) for s in stations_data]
id_to_idx = {sid: i for i, sid in enumerate(station_ids)}

def great_circle_miles(lat1, lon1, lat2, lon2, radius=R):
    deg_to_rad = math.pi / 180.0
    phi1 = (90.0 - lat1) * deg_to_rad
    phi2 = (90.0 - lat2) * deg_to_rad
    theta1 = lon1 * deg_to_rad
    theta2 = lon2 * deg_to_rad
    cos_arc = (math.sin(phi1) * math.sin(phi2) * math.cos(theta1 - theta2)
               + math.cos(phi1) * math.cos(phi2))
    cos_arc = max(-1.0, min(1.0, cos_arc))
    return math.acos(cos_arc) * radius

coords = [(depot['latitude'], depot['longitude'])]
for s in stations_data:
    coords.append((s['latitude'], s['longitude']))
# index 0 = depot, 1..n = stations (station idx i -> coords[i+1])

def dist(a_node, b_node):
    # a_node, b_node: 'START'/'END' or int station idx
    la = coords[0] if a_node in ('START', 'END') else coords[a_node + 1]
    lb = coords[0] if b_node in ('START', 'END') else coords[b_node + 1]
    return great_circle_miles(la[0], la[1], lb[0], lb[1])

stations = list(range(n))
vehicles = list(range(K))
START, END = 'START', 'END'
from_nodes = [START] + stations
to_nodes = stations + [END]
arcs = [(i, j) for i in from_nodes for j in to_nodes if i != j]

D = {(i, j): dist(i, j) for i, j in arcs}

targets = [s['net_rebalancing_target'] for s in stations_data]
initial = [s['initial_bikes'] for s in stations_data]
scap = [s['station_capacity'] for s in stations_data]

model = Model("bike_rebalancing")
model.hideOutput()

x = {}
for v in vehicles:
    for i, j in arcs:
        x[v, i, j] = model.addVar(vtype="B", name=f"x_{v}_{i}_{j}")

# degree: each vehicle must start and end depot exactly once (must visit >=1 station)
for v in vehicles:
    model.addCons(quicksum(x[v, START, j] for j in stations) == 1)
    model.addCons(quicksum(x[v, i, END] for i in stations) == 1)
    for i in stations:
        incoming = quicksum(x[v, j, i] for j in from_nodes if j != i)
        outgoing = quicksum(x[v, i, j] for j in to_nodes if j != i)
        model.addCons(incoming == outgoing)
        model.addCons(outgoing <= 1)

# MTZ subtour elimination per vehicle
order = {}
for v in vehicles:
    for i in stations:
        order[v, i] = model.addVar(vtype="C", lb=1, ub=n, name=f"order_{v}_{i}")
for v in vehicles:
    for i in stations:
        for j in stations:
            if i != j:
                model.addCons(order[v, i] - order[v, j] + n * x[v, i, j] <= n - 1)

visit = {}
for v in vehicles:
    for i in stations:
        visit[v, i] = quicksum(x[v, i, j] for j in to_nodes if j != i)

# service variable: signed net operation at stop (pickup positive, dropoff negative)
service = {}
for v in vehicles:
    for i in stations:
        service[v, i] = model.addVar(vtype="I", lb=-CAP, ub=CAP, name=f"service_{v}_{i}")
        model.addCons(service[v, i] <= CAP * visit[v, i])
        model.addCons(service[v, i] >= -CAP * visit[v, i])

# load variables (load AFTER visiting station i, for vehicle v)
load = {}
for v in vehicles:
    for i in stations:
        load[v, i] = model.addVar(vtype="C", lb=0, ub=CAP, name=f"load_{v}_{i}")
end_load = {v: model.addVar(vtype="C", lb=0, ub=CAP, name=f"endload_{v}") for v in vehicles}

M = 2 * CAP
for v in vehicles:
    # from START to station j: load[j] = 0 + service[j]
    for j in stations:
        model.addCons(load[v, j] - service[v, j] <= M * (1 - x[v, START, j]))
        model.addCons(load[v, j] - service[v, j] >= -M * (1 - x[v, START, j]))
    # station i to station j
    for i in stations:
        for j in stations:
            if i != j:
                model.addCons(load[v, j] - load[v, i] - service[v, j] <= M * (1 - x[v, i, j]))
                model.addCons(load[v, j] - load[v, i] - service[v, j] >= -M * (1 - x[v, i, j]))
    # station i to END: end_load = load[i]
    for i in stations:
        model.addCons(end_load[v] - load[v, i] <= M * (1 - x[v, i, END]))
        model.addCons(end_load[v] - load[v, i] >= -M * (1 - x[v, i, END]))

# station-level net change and hard inventory bounds
net_change = {}
dev = {}
for i in stations:
    net_change[i] = quicksum(service[v, i] for v in vehicles)
    # final inventory = initial - net_change, must be in [0, capacity]
    model.addCons(net_change[i] <= initial[i])
    model.addCons(net_change[i] >= initial[i] - scap[i])
    dev[i] = model.addVar(vtype="I", lb=0, name=f"dev_{i}")
    model.addCons(net_change[i] - targets[i] <= dev[i])
    model.addCons(targets[i] - net_change[i] <= dev[i])

travel_distance = quicksum(D[i, j] * x[v, i, j] for v in vehicles for i, j in arcs)
penalty_cost = PEN * quicksum(dev[i] for i in stations)
model.setObjective(travel_distance + penalty_cost, "minimize")

model.setParam("limits/time", 300.0)
model.setParam("limits/gap", 0.0)
model.setParam("randomization/randomseedshift", 0)

model.optimize()

status = str(model.getStatus())
print("status:", status)
if model.getNSols() == 0:
    raise RuntimeError("no feasible solution found")

print("objective:", model.getObjVal())

# Extract solution
sol_x = {}
for v in vehicles:
    for i, j in arcs:
        val = model.getVal(x[v, i, j])
        if val > 0.5:
            sol_x[v, i, j] = 1

sol_service = {}
for v in vehicles:
    for i in stations:
        sol_service[v, i] = model.getVal(service[v, i])

sol_load = {(v, i): model.getVal(load[v, i]) for v in vehicles for i in stations}
sol_end_load = {v: model.getVal(end_load[v]) for v in vehicles}

# reconstruct routes
routes = {}
for v in vehicles:
    outgoing = {}
    for (vv, i, j) in sol_x:
        if vv == v:
            outgoing[i] = j
    route = [START]
    cur = START
    seen = set()
    while cur != END:
        nxt = outgoing[cur]
        route.append(nxt)
        if nxt in seen:
            raise RuntimeError(f"cycle detected vehicle {v}")
        seen.add(nxt)
        cur = nxt
    routes[v] = route

json.dump({
    "routes": {str(v): routes[v] for v in vehicles},
    "service": {f"{v}_{i}": sol_service[v, i] for v in vehicles for i in stations},
    "load": {f"{v}_{i}": sol_load[v, i] for v in vehicles for i in stations},
    "end_load": {str(v): sol_end_load[v] for v in vehicles},
    "objective": model.getObjVal(),
}, open('/root/solution_raw.json', 'w'), indent=2)

print("Routes:")
for v in vehicles:
    print(v, routes[v])
